import{_ as a,o as t,c as r,ag as o}from"./chunks/framework.7He2WLS4.js";const u=JSON.parse('{"title":"Features Overview","description":"Comprehensive overview of all NectoProxy features for HTTP/HTTPS debugging and traffic analysis.","frontmatter":{"title":"Features Overview","description":"Comprehensive overview of all NectoProxy features for HTTP/HTTPS debugging and traffic analysis."},"headers":[],"relativePath":"features/index.md","filePath":"features/index.md","lastUpdated":1772297611000}'),i={name:"features/index.md"};function s(n,e,d,c,l,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="features-overview" tabindex="-1">Features Overview <a class="header-anchor" href="#features-overview" aria-label="Permalink to &quot;Features Overview&quot;">​</a></h1><p>NectoProxy is a full-featured HTTP/HTTPS debugging proxy with a modern Web UI. It provides everything you need to inspect, intercept, modify, and analyze network traffic flowing through your applications.</p><p>This page provides a categorized summary of every feature available in NectoProxy. Click through to the individual feature pages for detailed documentation, configuration options, and practical examples.</p><hr><h2 id="core-features" tabindex="-1">Core Features <a class="header-anchor" href="#core-features" aria-label="Permalink to &quot;Core Features&quot;">​</a></h2><p>The foundation of NectoProxy&#39;s debugging capabilities. These features give you full control over HTTP traffic flowing through the proxy.</p><h3 id="traffic-inspection" tabindex="-1"><a href="./traffic-inspection.html">Traffic Inspection</a> <a class="header-anchor" href="#traffic-inspection" aria-label="Permalink to &quot;[Traffic Inspection](./traffic-inspection)&quot;">​</a></h3><p>Real-time monitoring of all HTTP and HTTPS traffic. View complete request and response details including headers, bodies with syntax highlighting, timing breakdowns, and TLS certificate information. Supports filtering by method, status code, URL, host, and content type. Handles thousands of entries through a virtualized, high-performance list.</p><h3 id="rules-engine" tabindex="-1"><a href="./rules-engine.html">Rules Engine</a> <a class="header-anchor" href="#rules-engine" aria-label="Permalink to &quot;[Rules Engine](./rules-engine)&quot;">​</a></h3><p>A powerful rules system that lets you intercept and transform traffic on the fly. Supports 8 distinct rule actions -- Mock, Block, Modify Request, Modify Response, Map Local, Map Remote, Delay, and Throttle. Define matching conditions using URL patterns (glob, wildcard, regex), HTTP methods, headers, and body content. Rules are evaluated by priority and can be toggled on and off individually.</p><h3 id="breakpoints" tabindex="-1"><a href="./breakpoints.html">Breakpoints</a> <a class="header-anchor" href="#breakpoints" aria-label="Permalink to &quot;[Breakpoints](./breakpoints)&quot;">​</a></h3><p>Pause HTTP requests or responses mid-flight so you can inspect and modify them before they continue. Set conditions based on URL patterns, methods, and headers with AND/OR logic. When a breakpoint triggers, NectoProxy presents the intercepted message in the UI for live editing. Configurable timeout with auto-continue ensures breakpoints do not block traffic indefinitely.</p><h3 id="network-conditioning" tabindex="-1"><a href="./network-conditioning.html">Network Conditioning</a> <a class="header-anchor" href="#network-conditioning" aria-label="Permalink to &quot;[Network Conditioning](./network-conditioning)&quot;">​</a></h3><p>Simulate real-world network conditions to test how your application behaves under constrained environments. Choose from 11 built-in profiles ranging from Slow 2G to WiFi, or create custom profiles with precise control over download bandwidth, upload bandwidth, latency, jitter, and packet loss. Includes an Offline mode for testing disconnected scenarios.</p><hr><h2 id="protocol-support" tabindex="-1">Protocol Support <a class="header-anchor" href="#protocol-support" aria-label="Permalink to &quot;Protocol Support&quot;">​</a></h2><p>NectoProxy goes beyond basic HTTP proxying to support additional protocols and advanced networking scenarios.</p><h3 id="websocket-support" tabindex="-1"><a href="./websocket-support.html">WebSocket Support</a> <a class="header-anchor" href="#websocket-support" aria-label="Permalink to &quot;[WebSocket Support](./websocket-support)&quot;">​</a></h3><p>Full inspection of WebSocket (WS) and secure WebSocket (WSS) connections. Capture and display individual frames including text, binary, ping, pong, and close frames. Track frame direction (client-to-server or server-to-client), view opcode information, and stream frames in real time as they are exchanged.</p><h3 id="ssl-passthrough" tabindex="-1"><a href="./ssl-passthrough.html">SSL Passthrough</a> <a class="header-anchor" href="#ssl-passthrough" aria-label="Permalink to &quot;[SSL Passthrough](./ssl-passthrough)&quot;">​</a></h3><p>Bypass MITM decryption for specific domains. Traffic to passthrough domains flows through the proxy without being intercepted or decrypted. Essential for domains that use certificate pinning, financial services, or situations where compliance requirements prevent traffic inspection. Supports wildcard domain patterns.</p><h3 id="dns-mapping" tabindex="-1"><a href="./dns-mapping.html">DNS Mapping</a> <a class="header-anchor" href="#dns-mapping" aria-label="Permalink to &quot;[DNS Mapping](./dns-mapping)&quot;">​</a></h3><p>Override DNS resolution for specific domains by mapping them to custom IP addresses. Useful for redirecting traffic to staging servers, testing against local development environments, or performing A/B testing across different backends -- all without modifying system DNS or hosts files.</p><h3 id="upstream-proxy" tabindex="-1"><a href="./upstream-proxy.html">Upstream Proxy</a> <a class="header-anchor" href="#upstream-proxy" aria-label="Permalink to &quot;[Upstream Proxy](./upstream-proxy)&quot;">​</a></h3><p>Chain NectoProxy with another upstream proxy. Supports HTTP, HTTPS, SOCKS4, and SOCKS5 protocols with optional authentication. Configure bypass rules to exclude specific domains from upstream routing. Ideal for corporate proxy environments, routing through Tor, or VPN integration.</p><hr><h2 id="analysis-export" tabindex="-1">Analysis &amp; Export <a class="header-anchor" href="#analysis-export" aria-label="Permalink to &quot;Analysis &amp; Export&quot;">​</a></h2><p>Tools for deeper analysis, sharing, and automation of captured traffic data.</p><h3 id="har-export-import" tabindex="-1"><a href="./har-export-import.html">HAR Export &amp; Import</a> <a class="header-anchor" href="#har-export-import" aria-label="Permalink to &quot;[HAR Export &amp; Import](./har-export-import)&quot;">​</a></h3><p>Export captured sessions to the industry-standard HTTP Archive (HAR 1.2) format. Import HAR files from other tools such as Chrome DevTools or Charles Proxy. Export entire sessions or selected entries. Share captured traffic with teammates for collaborative debugging.</p><h3 id="code-generation" tabindex="-1"><a href="./code-generation.html">Code Generation</a> <a class="header-anchor" href="#code-generation" aria-label="Permalink to &quot;[Code Generation](./code-generation)&quot;">​</a></h3><p>Generate ready-to-use code snippets from any captured request. Supports 8 languages and tools: cURL, Python (requests), Node.js (fetch), Go (net/http), PHP (cURL), Rust (reqwest), HTTPie, and PowerShell (Invoke-WebRequest). Copy generated code to your clipboard with a single click.</p><h3 id="request-replay" tabindex="-1"><a href="./request-replay.html">Request Replay</a> <a class="header-anchor" href="#request-replay" aria-label="Permalink to &quot;[Request Replay](./request-replay)&quot;">​</a></h3><p>Re-send any captured request with optional modifications. Edit the URL, method, headers, or body before replaying. Compare the replayed response against the original to identify differences. Valuable for regression testing and debugging intermittent issues.</p><h3 id="request-comparison" tabindex="-1"><a href="./request-comparison.html">Request Comparison</a> <a class="header-anchor" href="#request-comparison" aria-label="Permalink to &quot;[Request Comparison](./request-comparison)&quot;">​</a></h3><p>Select any two traffic entries and view a side-by-side diff. Compare headers, bodies, and metadata with visual highlighting of additions, removals, and modifications. JSON-aware diffing ensures structured data is compared meaningfully. Useful for before-and-after testing workflows.</p><h3 id="security-scanning" tabindex="-1"><a href="./security-scanning.html">Security Scanning</a> <a class="header-anchor" href="#security-scanning" aria-label="Permalink to &quot;[Security Scanning](./security-scanning)&quot;">​</a></h3><p>Automated security analysis of captured traffic. Four built-in scanners check for missing security headers, insecure cookie attributes, overly permissive CORS configurations, and information disclosure. Each finding includes a severity level (Critical, High, Medium, Low, Info) and actionable remediation guidance.</p><h3 id="annotations" tabindex="-1"><a href="./annotations.html">Annotations</a> <a class="header-anchor" href="#annotations" aria-label="Permalink to &quot;[Annotations](./annotations)&quot;">​</a></h3><p>Add text notes and color-coded tags to any traffic entry. Mark important requests, leave context for teammates, or organize findings during a debugging session. Annotations are searchable and timestamped, making it easy to revisit specific observations later.</p><hr><h2 id="ui-features" tabindex="-1">UI Features <a class="header-anchor" href="#ui-features" aria-label="Permalink to &quot;UI Features&quot;">​</a></h2><p>The NectoProxy Web UI is designed for efficiency. These features help you organize, navigate, and find traffic quickly.</p><h3 id="sessions" tabindex="-1"><a href="./sessions.html">Sessions</a> <a class="header-anchor" href="#sessions" aria-label="Permalink to &quot;[Sessions](./sessions)&quot;">​</a></h3><p>Organize captured traffic into named sessions. Create separate sessions for different debugging tasks, switch between them without losing data, and view per-session statistics including request count and total bytes transferred. Export individual sessions for archiving or sharing.</p><h3 id="dashboard" tabindex="-1"><a href="./dashboard.html">Dashboard</a> <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;[Dashboard](./dashboard)&quot;">​</a></h3><p>A visual analytics panel with real-time charts and statistics. View requests per second, error rates, response time histograms, traffic by domain, status code distribution, and top slowest requests. Statistical summary cards show total requests, average response time, and error rate at a glance.</p><h3 id="search-filtering" tabindex="-1"><a href="./search.html">Search &amp; Filtering</a> <a class="header-anchor" href="#search-filtering" aria-label="Permalink to &quot;[Search &amp; Filtering](./search)&quot;">​</a></h3><p>Find traffic quickly with the filter bar supporting method, status code, URL, host, and content type filters. Use global search across all sessions with <code>Ctrl+Shift+F</code>. Access the command palette with <code>Ctrl+K</code> / <code>Cmd+K</code> for quick navigation. Search includes autocomplete suggestions and remembers recent queries.</p><h3 id="keyboard-shortcuts" tabindex="-1"><a href="./keyboard-shortcuts.html">Keyboard Shortcuts</a> <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;[Keyboard Shortcuts](./keyboard-shortcuts)&quot;">​</a></h3><p>Navigate and control NectoProxy entirely from the keyboard. Shortcuts cover navigation, traffic control (pause, resume, clear), panel toggles, search, and the command palette. A built-in keyboard shortcuts help panel displays all available bindings.</p><hr><div class="tip custom-block"><p class="custom-block-title">Getting Started</p><p>If you are new to NectoProxy, start with the <a href="./traffic-inspection.html">Traffic Inspection</a> feature to understand the basics of capturing and viewing HTTP traffic. Then explore the <a href="./rules-engine.html">Rules Engine</a> to learn how to modify traffic on the fly.</p></div><div class="info custom-block"><p class="custom-block-title">Feature Requests</p><p>NectoProxy is under active development. If you have feature requests or suggestions, please open an issue on the <a href="https://github.com/nicktecno/nectoproxy" target="_blank" rel="noreferrer">GitHub repository</a>.</p></div>',54)])])}const f=a(i,[["render",s]]);export{u as __pageData,f as default};
